document.addEventListener("keydown",e=>{if(view!=="kids"||KV.scr!=="derby"||!kDby)return;const m={ArrowLeft:"kL",ArrowRight:"kR",ArrowUp:"kU",ArrowDown:"kD"}[e.key];if(m){e.preventDefault();kDby[m]=true}if(e.key===" "){e.preventDefault();kDbBoost()}if(e.key==="z"||e.key==="x")kDbZap()});
document.addEventListener("keyup",e=>{if(!kDby)return;const m={ArrowLeft:"kL",ArrowRight:"kR",ArrowUp:"kU",ArrowDown:"kD"}[e.key];if(m)kDby[m]=false});
const KDBCOACH=["🕹️ Push the joystick (bottom-left) to drive to a car!","💥 Now CRASH into a car, front bumper first!","🟠 Great hit! Tap the orange BOOST button, then crash!","⚡ Now tap the blue ZAP button to shoot lightning!","🏆 Break cars to zero health for a KO: +100! Reach the 🎯 goal!"];
function kDbCoachOn(){const d=KS().derby||{};return d.coach===true}
function kDbCoach(D,dt){if(D.coach>4)return;const me=D.cars[0],sp=Math.hypot(me.vx,me.vy);if(D.coachT===0)kLine(KDBCOACH[D.coach].replace(/[👆💥🟠🏆🎯]/g,""),2);D.coachT+=dt;
  const next=D.coach===0?(D.touched||D.kU||D.kL||D.kR):D.coach===1?D.score>0:D.coach===2?D.boosted:D.coach===3?D.zapped:D.coachT>5;if(next&&D.coachT>1.2){D.coach++;D.coachT=0;if(D.coach<5)kBeep("chime")}}
function kDbZapBtn(D){return{x:D.W-52,y:D.H-150,r:30}}
function kZapSnd(){if(!kAudio()||KS().sound===false)return;const t=kAC.currentTime;kTone(1500,t,.06,"square",.04);kTone(900,t+.03,.08,"sawtooth",.035);kTone(500,t+.07,.08,"square",.025)}
function kDbShoot(D,o,k,tg){const hx=Math.sin(o.a),hy=-Math.cos(o.a),sp=k==="rocket"?330:k==="zap"?560:k==="shell"?440:280;D.shots.push({k,x:o.x+hx*(o.r+10),y:o.y+hy*(o.r+10),vx:hx*sp+o.vx*.5,vy:hy*sp+o.vy*.5,t:0,life:k==="rocket"?2.6:k==="shell"?1.3:1.1,own:o,tg})}
function kDbZap(){const D=kDby;if(!D||D.over||D.q||D.rules||D.cd>0)return;const me=D.cars[0];if(!me||!me.alive)return;
  if(D.rockets>0){const tg=D.cars.filter(o=>o.ai&&o.alive).sort((a,b)=>Math.hypot(a.x-me.x,a.y-me.y)-Math.hypot(b.x-me.x,b.y-me.y))[0];D.rockets--;kDbShoot(D,me,"rocket",tg);kBeep("whoosh");D.zapped=1;return}
  if(D.zapCd>0)return;if(D.ammo<1){D.tip="⚡ Recharging… wait a second!";D.tipT=1;return}D.ammo--;const tank=me.sh==="tank";D.zapCd=tank?.6:.3;kDbShoot(D,me,tank?"shell":"zap");if(tank){kBeep("boom");D.shake=Math.max(D.shake,.15);me.vx-=Math.sin(me.a)*40;me.vy+=Math.cos(me.a)*40}else kZapSnd();D.zapped=1}
function kDbShots(D,dt){for(const b of D.shots){b.t+=dt;if(b.k==="rocket"&&b.tg&&b.tg.alive){const want=Math.atan2(b.tg.x-b.x,-(b.tg.y-b.y)),cur=Math.atan2(b.vx,-b.vy),na=cur+Math.max(-4*dt,Math.min(4*dt,kAng(want-cur))),sp=Math.hypot(b.vx,b.vy);b.vx=Math.sin(na)*sp;b.vy=-Math.cos(na)*sp;if(Math.random()<.5)kDbFx(D,{k:"smoke",x:b.x,y:b.y})}
    b.x+=b.vx*dt;b.y+=b.vy*dt;if(b.x<0||b.y<0||b.x>D.AW||b.y>D.AH||b.t>b.life||D.obs.some(s=>Math.hypot(b.x-s.x,b.y-s.y)<s.r)){b.dead=1;kDbFx(D,{k:"deb",x:b.x,y:b.y,vx:0,vy:0,col:b.k==="zap"?"#9be7ff":"#ff9f1c"});continue}
    for(const o of D.cars){if(b.dead||!o.alive||o===b.own)continue;if(Math.hypot(o.x-b.x,o.y-b.y)<o.r+6){b.dead=1;const n=Math.hypot(b.vx,b.vy)||1,push=b.k==="rocket"?230:b.k==="shell"?200:90;o.vx+=b.vx/n*push;o.vy+=b.vy/n*push;o.av=(o.av||0)+(Math.random()-.5)*(b.k==="rocket"?8:3);
      if(b.k==="rocket"||b.k==="shell"){kDbFx(D,{k:"boom",x:b.x,y:b.y});kBeep("boom");D.shake=Math.max(D.shake,.3)}else kBeep("spark");for(let i=0;i<6;i++)kDbFx(D,{k:"deb",x:b.x,y:b.y,vx:(Math.random()-.5)*160,vy:(Math.random()-.5)*160,col:b.k==="zap"?"#9be7ff":"#ffd23f"});
      kDbDmg(D,o,(b.k==="rocket"?22:b.k==="shell"?16:b.k==="zap"?8:6)*(b.own.mega>0?1.5:1),b.own,b.x,b.y)}}}D.shots=D.shots.filter(b=>!b.dead)}
function kDbShotDraw(c,D){for(const b of D.shots){if(b.k==="zap"){c.strokeStyle="rgba(120,220,255,.65)";c.lineWidth=5;c.beginPath();c.moveTo(b.x,b.y);c.lineTo(b.x-b.vx*.045,b.y-b.vy*.045);c.stroke();c.save();c.shadowColor="#3fb6ff";c.shadowBlur=14;c.fillStyle="#e8fcff";c.beginPath();c.arc(b.x,b.y,6,0,7);c.fill();c.restore()}
    else if(b.k==="rocket"){c.save();c.translate(b.x,b.y);c.rotate(Math.atan2(b.vx,-b.vy));c.fillStyle="#ff8a00";c.beginPath();c.moveTo(-4,10);c.lineTo(4,10);c.lineTo(0,20+Math.random()*7);c.closePath();c.fill();c.fillStyle="#e5e7eb";c.beginPath();c.roundRect(-4,-10,8,20,4);c.fill();c.fillStyle="#e31937";c.beginPath();c.moveTo(-4,-8);c.lineTo(0,-17);c.lineTo(4,-8);c.closePath();c.fill();c.restore()}
    else if(b.k==="shell"){c.strokeStyle="rgba(255,150,40,.6)";c.lineWidth=4;c.beginPath();c.moveTo(b.x,b.y);c.lineTo(b.x-b.vx*.05,b.y-b.vy*.05);c.stroke();c.fillStyle="#374151";c.beginPath();c.arc(b.x,b.y,7,0,7);c.fill();c.fillStyle="#9ca3af";c.beginPath();c.arc(b.x-2,b.y-2,2.5,0,7);c.fill()}
    else{c.fillStyle="#ff9f1c";c.beginPath();c.arc(b.x,b.y,6,0,7);c.fill();c.strokeStyle="rgba(255,159,28,.45)";c.lineWidth=3;c.beginPath();c.arc(b.x,b.y,10,0,7);c.stroke()}}}
