const KPAINTX={paint_cherry:["Midnight Cherry","#5c0a1e"],paint_blue:["Ultra Blue","#1a4fff"],paint_gold:["Cyber Gold","#d4a017"],paint_green:["Matrix Green","#00c853"],paint_purple:["Galaxy Purple","#6d28d9"],paint_pink:["Glow Pink","#ff3ea5"],paint_chrome:["Liquid Chrome","#e5e7eb"]};
const KHORNS=[["horn","📯","Horn"],["goat","🐐","Goat","bb_goat"],["fart","💨","Emissions","bb_fart"],["clap","👏","Applause","bb_clap"],["robot","🤖","Robot","bb_robot"],["moo","🐄","Cow","bb_moo"]];
const KEGGS=["rainbow","santa","track","glow","bio","warp","ramp"];
function kHackGive(){const k=KS();k.hack=k.hack||{};const n=Object.keys(k.hack).length;if(n<KHACK.length){const H=KHACK[n];k.hack[H[0]]=Date.now();return H}k.coins+=20;return ["loot","💰","Bonus hack loot: +20 ⚡","All 20 Tesla mods unlocked!"]}
function kEggsOn(){const k=KS(),u=k.hack||{},e=(k.drive&&k.drive.eggs)||{},o={};for(const id of KEGGS.concat(["armor"]))o[id]=!!u[id]&&e[id]!==false;return o}
let kNoiseB=null;
function kHorn(kind){const k=KS();kind=kind||(k.drive&&k.drive.horn)||"horn";if(kind==="horn"||!kAudio()||k.sound===false){if(kind==="horn")kHonk();return}const t=kAC.currentTime,g=kAC.createGain();g.connect(kMaster);g.gain.value=0;
  const env=(a,d,v)=>{g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(v,t+a);g.gain.setValueAtTime(v,t+Math.max(a,d-.08));g.gain.linearRampToValueAtTime(0,t+d)};
  if(kind==="clap"){if(!kNoiseB){kNoiseB=kAC.createBuffer(1,kAC.sampleRate*.08,kAC.sampleRate);const d=kNoiseB.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=(Math.random()*2-1)*(1-i/d.length)}g.gain.value=.22;const f=kAC.createBiquadFilter();f.type="bandpass";f.frequency.value=1600;f.connect(g);for(let i=0;i<22;i++){const s=kAC.createBufferSource();s.buffer=kNoiseB;s.connect(f);s.start(t+Math.random()*1.3)}return}
  const o=kAC.createOscillator(),f=kAC.createBiquadFilter();f.type="lowpass";f.frequency.value=2400;o.connect(f);f.connect(g);const lfo=(fr,amt,type)=>{const l=kAC.createOscillator(),lg=kAC.createGain();l.type=type||"sine";l.frequency.value=fr;lg.gain.value=amt;l.connect(lg);lg.connect(o.frequency);l.start(t);l.stop(t+1.2)};
  if(kind==="goat"){o.type="sawtooth";o.frequency.setValueAtTime(620,t);o.frequency.linearRampToValueAtTime(470,t+.7);lfo(11,60);env(.03,.75,.09);o.start(t);o.stop(t+.8)}
  else if(kind==="fart"){o.type="sawtooth";f.frequency.value=650;o.frequency.setValueAtTime(115,t);o.frequency.exponentialRampToValueAtTime(52,t+.8);lfo(24,30,"square");env(.02,.85,.17);o.start(t);o.stop(t+.9)}
  else if(kind==="moo"){o.type="sawtooth";f.frequency.value=900;o.frequency.setValueAtTime(150,t);o.frequency.linearRampToValueAtTime(178,t+.3);o.frequency.linearRampToValueAtTime(118,t+1);env(.12,1.05,.13);o.start(t);o.stop(t+1.1)}
  else{o.type="square";[880,660,990,520,1200].forEach((fr,i)=>o.frequency.setValueAtTime(fr,t+i*.09));env(.01,.5,.06);o.start(t);o.stop(t+.55)}}
function kHornIc(){const h=(KS().drive&&KS().drive.horn)||"horn";return (KHORNS.find(x=>x[0]===h)||KHORNS[0])[1]}
/* ---------- Road Trip extras: rainbow road, ramps, Boring tunnel, hints ---------- */
function kRoadFill(c,D,RX,RW,H){if(D.eg.rainbow){const off=(D.dist*1500*1.5)%240;for(let y=-240+off,i=0;y<H;y+=40,i++){c.fillStyle=`hsl(${(i%6)*60},85%,55%)`;c.fillRect(RX,y,RW,41)}c.fillStyle="rgba(0,0,0,.2)";c.fillRect(RX,0,RW,H)}else{c.fillStyle="#2b2f3a";c.fillRect(RX,0,RW,H)}}
function kRampDraw(c,x,y,LW){const w=LW-18;c.fillStyle="#f97316";c.beginPath();c.moveTo(x-w/2,y+18);c.lineTo(x+w/2,y+18);c.lineTo(x+w/2-6,y-18);c.lineTo(x-w/2+6,y-18);c.closePath();c.fill();c.fillStyle="#fde68a";for(let i=-1;i<=1;i++){c.beginPath();c.moveTo(x+i*14,y-12);c.lineTo(x+i*14+7,y);c.lineTo(x+i*14-7,y);c.closePath();c.fill()}c.fillStyle="#7c2d12";c.fillRect(x-w/2,y+14,w,4)}
function kTunnel(c,D,RX,RW,W,H){if(!D.tunSaid){D.tunSaid=1;kLine("Entering the Boring tunnel!",2);kBeep("whoosh")}const fa=Math.max(0,Math.min(1,(D.t-38)/.6,(46-D.t)/.6));c.globalAlpha=fa;c.fillStyle="#07080d";c.fillRect(0,0,RX-4,H);c.fillRect(RX+RW+4,0,W-RX-RW-4,H);c.fillStyle="rgba(0,0,0,.35)";c.fillRect(RX,0,RW,H);
  const off=(D.dist*1500*1.5)%30;for(let y=-30+off,i=0;y<H;y+=30,i++){c.fillStyle=`hsl(${(i*25+D.t*160)%360},100%,60%)`;c.fillRect(RX-11,y,5,14);c.fillRect(RX+RW+6,y,5,14)}c.globalAlpha=1;if(D.t<40.5){c.fillStyle=`rgba(255,255,255,${fa*.9})`;c.font="900 16px system-ui";c.textAlign="center";c.textBaseline="middle";c.fillText("🕳️ BORING TUNNEL",W/2,140)}}
function kDriveCar(c,D,carY,SP,night){const C=D.car,R=D.mode==="roadster";if(D.t-(D.hitT==null?-9:D.hitT)<1.5&&Math.floor(D.t*12)%2)return;const sz=KCSZ[C[3]],js=D.jump>0?1+Math.sin(D.jump/1.15*Math.PI)*.35:1;c.textAlign="center";c.textBaseline="middle";
  if(D.eg.glow&&!SP){const hue=(D.t*120)%360,g=c.createRadialGradient(D.x,carY,10,D.x,carY,sz[1]*.75);g.addColorStop(0,`hsla(${hue},100%,60%,.75)`);g.addColorStop(1,`hsla(${hue},100%,60%,0)`);c.fillStyle=g;c.beginPath();c.ellipse(D.x,carY,sz[0],sz[1]*.7,0,0,7);c.fill()}
  if(D.eg.santa&&!SP){const bob=Math.sin(D.t*12)*3,ty=carY-sz[1]/2;c.strokeStyle="#c8a24a";c.lineWidth=1.5;c.beginPath();c.moveTo(D.x-14,ty-22);c.lineTo(D.x-6,ty);c.moveTo(D.x+14,ty-22);c.lineTo(D.x+6,ty);c.stroke();c.font="26px serif";c.fillText("🦌",D.x-14,ty-34+bob);c.fillText("🦌",D.x+14,ty-34-bob)}
  if(D.jump>0){c.fillStyle="rgba(0,0,0,.25)";c.beginPath();c.ellipse(D.x+14*(js-1)*3,carY+22*(js-1)*3,sz[0]*.55,sz[1]*.45,0,0,7);c.fill()}
  c.save();c.translate(D.x,carY);c.scale(js,js);kTesla(c,0,0,sz[0],sz[1],R?"#e31937":D.col,C[3],{fly:SP||D.fly>0,boost:D.plaid>0,t:D.t,night});c.restore();
  if(D.eg.bio&&D.t<5){c.strokeStyle="rgba(63,182,255,.85)";c.lineWidth=3;c.beginPath();c.ellipse(D.x,carY,sz[0]*.95,sz[1]*.68,0,0,7);c.stroke()}if(D.eg.santa&&!SP){c.font="18px serif";c.fillText("🎅",D.x,carY+6)}}
const KDTIPS=["Grab ⚡ bolts: they charge your battery. Grab them fast for COMBOS!","🔋 boosts give you Plaid speed. You can't crash during a boost!","🦘 Ramps make you jump over everything!","🤖 Autopilot dodges cones and cars, but YOU answer the Brain Gates.","Red SUPERCHARGER lanes refill your battery a lot.","Hold 🛑 Regen to slow down and recharge, like a real Tesla!","📢 Honk and the car ahead moves over (every 3 seconds)."];
function kDriveHint(){const D=kDrv;if(!D||D.over)return;D.hintT=5;D.hints=(D.hints||0)+1;if(D.gate&&!D.gate.done&&!D.gate.hinted){D.gate.hinted=1;KS().hints++;D.tip="💡 Follow the green arrows (no bonus with a hint)"}else D.tip=KDTIPS[(D.hints-1)%KDTIPS.length];D.tipT=4;kBeep("chime")}
function kTankFire(){const D=kDrv;if(!D||D.over||(D.tankCd||0)>0)return;D.tankCd=.8;D.shells=(D.shells||[]).concat([{ln:D.lane,y:null}]);kBeep("boom");D.shake=Math.max(D.shake||0,.15);kVib(40)}
function kDriveOverlay(c,D,lx,W,H,carY,SP,dt){c.textAlign="center";c.textBaseline="middle";dt=dt||0;D.tankCd=Math.max(0,(D.tankCd||0)-dt);
  if(D.shells&&D.shells.length){for(const s of D.shells){if(s.y==null)s.y=carY-60;s.y-=720*dt;for(const o of D.obs)if(!o.done&&o.ln===s.ln&&(o.k==="cone"||o.k==="car")&&Math.abs(o.y-s.y)<42){o.done=1;o.k="gone";s.dead=1;D.bolts+=1;D.fx=(D.fx||[]).concat([{x:lx(o.ln),y:o.y,t:0,k:"spark",txt:"💥 BOOM! +1"},{x:lx(o.ln),y:o.y,t:0,k:"smoke"}]);kBeep("boom");break}if(s.y<-30)s.dead=1;
    c.fillStyle="rgba(255,150,40,.7)";c.beginPath();c.arc(lx(s.ln),s.y+10,5,0,7);c.fill();c.fillStyle="#374151";c.beginPath();c.arc(lx(s.ln),s.y,7,0,7);c.fill()}D.shells=D.shells.filter(s=>!s.dead)}
  if(D.plaid&&D.eg.warp){c.strokeStyle="rgba(170,200,255,.75)";c.lineWidth=2;const cx=W/2,cy=H*.35;for(let i=0;i<26;i++){const a=Math.random()*6.28,r1=30+Math.random()*60,r2=r1+80+Math.random()*120;c.beginPath();c.moveTo(cx+Math.cos(a)*r1,cy+Math.sin(a)*r1);c.lineTo(cx+Math.cos(a)*r2,cy+Math.sin(a)*r2);c.stroke()}}
  if(D.hintT>0&&!D.over){const danger=ln=>D.obs.some(o=>o.ln===ln&&!o.done&&(o.k==="cone"||o.k==="car")&&o.y>carY-260&&o.y<carY+30),good=ln=>D.obs.some(o=>o.ln===ln&&!o.done&&(o.k==="bolt"||o.k==="sc"||o.k==="ramp")&&o.y>carY-260&&o.y<carY);let best=D.lane;const G=D.gate&&!D.gate.done&&D.gate.hinted?D.gate:null;
    if(G)best=G.opts.indexOf(G.a);else{const safe=[0,1,2].filter(l=>!danger(l));best=safe.find(good)??(safe.includes(D.lane)?D.lane:safe.sort((a,b)=>Math.abs(a-D.lane)-Math.abs(b-D.lane))[0]??D.lane)}
    const x=lx(best),pu=Math.sin(D.t*10)*4;c.fillStyle="rgba(46,194,126,.9)";for(let i=0;i<3;i++){const y=carY-90-i*42+pu;c.beginPath();c.moveTo(x,y-14);c.lineTo(x+14,y+6);c.lineTo(x+6,y+6);c.lineTo(x,y-2);c.lineTo(x-6,y+6);c.lineTo(x-14,y+6);c.closePath();c.fill()}
    if(best!==D.lane){c.font="900 24px system-ui";c.fillText(best<D.lane?"◀":"▶",lx(D.lane)+(best<D.lane?-34:34),carY)}}
  const tip=D.t<3.5&&!SP?"◀ ▶ tap to switch lanes · grab ⚡ · dodge 🚧":D.tipT>0?D.tip:"";if(tip){c.font="bold 12px system-ui";const tw=Math.min(W-16,c.measureText(tip).width+24);c.fillStyle="rgba(22,140,90,.94)";c.beginPath();c.roundRect(W/2-tw/2,92,tw,26,9);c.fill();c.fillStyle="#fff";c.fillText(tip,W/2,105)}}
